func mapInts(nums []int, f func(int) int) {
    for i, n := range nums {
        nums[i] = f(n)
    }
}

func main() {
    values := []int{1, 2, 3}
    mapInts(values, double)
    fmt.Println(values)
    mapInts(values, func(n int) int {
        return n + 1
    })
    fmt.Println(values)
}

func add(a, b int) int {
    return a + b
}

func reduceInts(nums []int, seed int, op Op) int {
    result := seed
    for _, n := range nums {
        result = op(result, n)
    }
    return result
}

func main() {
    values := []int{2, 3, 4}
    fmt.Println(reduceInts(values, 0, add))
    mul := func(a, b int) int {
        return a * b
    }
    fmt.Println(reduceInts(values, 1, mul))
}

func evenHalf(n int) (int, bool) {
    return n / 2, n%2 == 0
}

func sum(xs []int, f func(int) (int, bool)) int {
    total := 0
    for _, n := range xs {
        v, ok := f(n)
        if ok {
            total += v
        }
    }
    return total
}

func main() {
    values := []int{4, 7, 10, 3}
    fmt.Println(sum(values, evenHalf))
}
